import { phase } from '/tmp/probe/p.mjs';
// cases: array of [lang, snippet]. Builds ONE markdown doc with many fences.
// Uses a sentinel paragraph between blocks so we can split the output.
const cases = JSON.parse(process.argv[2]);
const parts = [];
for (let i=0;i<cases.length;i++){
  const [lang, snip] = cases[i];
  parts.push('ZQSEP'+i+'ZQ');
  parts.push('```'+lang+'\n'+snip+'\n```');
}
parts.push('ZQSEP'+cases.length+'ZQ');
const doc = parts.join('\n\n');
const out = phase('e', doc);
// split on sentinel paragraphs
const chunks = out.split(/<p>ZQSEP\d+ZQ<\/p>/);
// chunks[0] = '' before first sentinel; chunks[i] is between sentinel i-1 and i
for (let i=0;i<cases.length;i++){
  const body = chunks[i+1];
  console.log('### ['+i+'] lang='+cases[i][0]+' IN='+JSON.stringify(cases[i][1]));
  console.log('OUT='+JSON.stringify(body===undefined?'<<MISSING>>':body));
}
EOF
